// Where to stay. Five areas around Villa Apparita, ~27 places we picked out
// ourselves.
//
// Facts are stored as data (minutes, room counts, amenity keys) and the
// bilingual prose is generated by the formatters at the bottom — writing
// "5 Min. mit dem Auto" / "5 min by car" by hand 27 times is how this file
// would rot. Only the blurbs are hand-written, and only once per place.

import type { L } from './i18n';

const bi = (en: string, de: string): L => ({ en, de });

/* ---------------------------------------------------------------- vocabulary */

export type Amenity =
	| 'pool'
	| 'breakfast'
	| 'kitchen'
	| 'restaurant'
	| 'garden'
	| 'walkable'
	| 'selfCatering'
	| 'animals'
	| 'view';

export const amenityLabel: Record<Amenity, L> = {
	pool: bi('Pool', 'Pool'),
	breakfast: bi('Breakfast', 'Frühstück'),
	kitchen: bi('Kitchen', 'Küche'),
	restaurant: bi('Restaurant', 'Restaurant'),
	garden: bi('Garden', 'Garten'),
	walkable: bi('Walk to the villa', 'Zu Fuß zur Villa'),
	selfCatering: bi('Self-catering', 'Selbstverpflegung'),
	animals: bi('Animals', 'Tiere'),
	view: bi('View', 'Aussicht'),
};

export type RoomKind = 'double' | 'family' | 'apartment' | 'room' | 'wholeHouse' | 'villa';

// German plurals often equal the singular, so both forms are stored rather
// than derived with a suffix rule.
export const roomLabel: Record<RoomKind, { one: L; many: L }> = {
	double: { one: bi('double room', 'Doppelzimmer'), many: bi('double rooms', 'Doppelzimmer') },
	family: { one: bi('family room', 'Familienzimmer'), many: bi('family rooms', 'Familienzimmer') },
	apartment: { one: bi('apartment', 'Ferienwohnung'), many: bi('apartments', 'Ferienwohnungen') },
	room: { one: bi('room', 'Zimmer'), many: bi('rooms', 'Zimmer') },
	wholeHouse: { one: bi('the whole house', 'das ganze Haus'), many: bi('houses', 'Häuser') },
	villa: { one: bi('villa', 'Villa'), many: bi('villas', 'Villen') },
};

// Small labels that belong to the fields above rather than to page prose, so
// they live here and not in copy.ts.
export const stayVocab = {
	reserved: bi('Held for our guests', 'Für unsere Gäste reserviert'),
	askUs: bi('Ask us', 'Fragt uns'),
};

/* -------------------------------------------------------------------- types */

export type RoomSpec = { kind: RoomKind; count?: number };
export type Distance = { minutes: number; km?: number; mode?: 'car' | 'foot' };

export type Stay = {
	/** Proper noun — never translated, rendered without `<Bi>`. */
	name: string;
	blurb: L;
	/** Omit to inherit the group's distance. */
	distance?: Distance;
	rooms?: RoomSpec[];
	sleeps?: number;
	amenities?: Amenity[];
	url?: string;
	email?: string;
	phone?: string;
	/** No booking route of its own — we broker it. */
	askUs?: boolean;
	/** Rooms already reserved for our guests. */
	reserved?: boolean;
	/** Free-form caveat, e.g. a minimum stay. */
	caveat?: L;
};

export type StayGroup = {
	/** Anchor target — `#stay-monticchiello`. */
	id: string;
	name: L;
	tagline: L;
	/** Default for the group's stays, and the rail's own line. */
	distance?: Distance;
	note?: L;
	/** Trailing link for groups that point somewhere else. */
	link?: { url: string; label: L };
	/** Empty for the Airbnb group, which is a wishlist rather than a list. */
	stays: Stay[];
};

