/* --------------------------------------------------------------- formatters */

export function distanceLabel(d: Distance, fromVilla = false): L {
	const unit =
		d.mode === 'foot'
			? bi(`${d.minutes} min on foot`, `${d.minutes} Min. zu Fuß`)
			: bi(`${d.minutes} min by car`, `${d.minutes} Min. mit dem Auto`);
	const km = d.km ? `${d.km} km · ` : '';
	const tail = fromVilla ? bi(' from the villa', ' von der Villa') : bi('', '');
	return bi(km + unit.en + tail.en, km + unit.de + tail.de);
}

export function roomsLabel(r: RoomSpec): L {
	const many = (r.count ?? 1) > 1;
	const l = many ? roomLabel[r.kind].many : roomLabel[r.kind].one;
	const n = many ? `${r.count} ` : '';
	return bi(n + l.en, n + l.de);
}

/**
 * One joined meta line per stay. Deliberately a single `L` rather than a row
 * of separate `<Bi>` elements — `Bi` renders both languages, so five fields
 * would cost ten spans per listing instead of two.
 */
export function metaLine(s: Stay): L {
	const parts: L[] = [];
	// Only a stay's own distance — the group's is already on the rail above,
	// and repeating it on all six Pienza rows just pads the line.
	if (s.distance) parts.push(distanceLabel(s.distance));
	for (const r of s.rooms ?? []) parts.push(roomsLabel(r));
	if (s.sleeps) parts.push(bi(`sleeps ${s.sleeps}`, `für ${s.sleeps} Personen`));
	for (const a of s.amenities ?? []) parts.push(amenityLabel[a]);
	const join = (k: keyof L) => parts.map((p) => p[k]).join(' · ');
	return bi(join('en'), join('de'));
}
